(function(global){
  const palette = ["#2563eb", "#10b981", "#f59e0b", "#ef4444", "#8b5cf6", "#06b6d4", "#f97316"];
  function cssColor(index){ return palette[index % palette.length]; }
  function asCanvas(item){ return item && item.canvas ? item.canvas : item; }
  function setup(canvas){
    const rect = canvas.getBoundingClientRect();
    const width = Math.max(1, Math.round(rect.width || canvas.clientWidth || canvas.parentElement?.clientWidth || 360));
    const height = Math.max(1, Math.round(rect.height || canvas.clientHeight || 240));
    const ratio = global.devicePixelRatio || 1;
    if (canvas.width !== Math.round(width * ratio) || canvas.height !== Math.round(height * ratio)) {
      canvas.width = Math.round(width * ratio);
      canvas.height = Math.round(height * ratio);
    }
    const ctx = canvas.getContext("2d");
    ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
    return { ctx, width, height };
  }
  function clear(ctx, width, height){ ctx.clearRect(0, 0, width, height); }
  function text(ctx, value, x, y, options = {}){
    ctx.fillStyle = options.color || "#64748b";
    ctx.font = (options.weight || 600) + " " + (options.size || 12) + "px Inter, system-ui, sans-serif";
    ctx.textAlign = options.align || "left";
    ctx.textBaseline = options.baseline || "alphabetic";
    ctx.fillText(String(value), x, y);
  }
  function roundRect(ctx, x, y, width, height, radius){
    const r = Math.min(radius, Math.abs(width) / 2, Math.abs(height) / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + width, y, x + width, y + height, r);
    ctx.arcTo(x + width, y + height, x, y + height, r);
    ctx.arcTo(x, y + height, x, y, r);
    ctx.arcTo(x, y, x + width, y, r);
    ctx.closePath();
  }
  function values(config){ return (config.data?.datasets || []).map((set) => (set.data || []).map((v) => Number(v) || 0)); }
  function maxValue(config){
    const goal = Number(config.options?.plugins?.goalLine?.value) || 0;
    const suggestedY = Number(config.options?.scales?.y?.suggestedMax) || 0;
    const suggestedX = Number(config.options?.scales?.x?.suggestedMax) || 0;
    return Math.max(1, goal, suggestedY, suggestedX, ...values(config).flat());
  }
  function drawAxes(ctx, area){
    ctx.strokeStyle = "#dbe4ef";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(area.x, area.y);
    ctx.lineTo(area.x, area.y + area.h);
    ctx.lineTo(area.x + area.w, area.y + area.h);
    ctx.stroke();
    ctx.strokeStyle = "rgba(148, 163, 184, .28)";
    for (let i = 1; i <= 3; i += 1) {
      const y = area.y + area.h - (area.h * i / 4);
      ctx.beginPath();
      ctx.moveTo(area.x, y);
      ctx.lineTo(area.x + area.w, y);
      ctx.stroke();
    }
  }
  function drawLabels(ctx, labels, area){
    const step = labels.length > 1 ? area.w / (labels.length - 1) : area.w;
    labels.forEach((label, index) => {
      if (labels.length > 8 && index % Math.ceil(labels.length / 6) !== 0 && index !== labels.length - 1) return;
      const x = labels.length > 1 ? area.x + step * index : area.x + area.w / 2;
      text(ctx, label, x, area.y + area.h + 24, { align: "center", size: 11 });
    });
  }
  function drawGoalLine(ctx, config, area){
    const goal = Number(config.options?.plugins?.goalLine?.value) || 0;
    if (!goal) return;
    const max = maxValue(config);
    const y = area.y + area.h - (area.h * goal / max);
    ctx.save();
    ctx.strokeStyle = config.options?.plugins?.goalLine?.color || "#f59e0b";
    ctx.lineWidth = 2;
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    ctx.moveTo(area.x, y);
    ctx.lineTo(area.x + area.w, y);
    ctx.stroke();
    ctx.setLineDash([]);
    text(ctx, config.options?.plugins?.goalLine?.label || "Goal", area.x + area.w - 4, y - 7, { align: "right", color: ctx.strokeStyle, size: 11, weight: 800 });
    ctx.restore();
  }
  function drawBar(ctx, config, area){
    const labels = config.data?.labels || [];
    const sets = config.data?.datasets || [];
    const max = maxValue(config);
    const group = area.w / Math.max(1, labels.length);
    const bar = Math.max(8, group / Math.max(2.4, sets.length + 1));
    sets.forEach((set, setIndex) => {
      (set.data || []).forEach((raw, index) => {
        const fill = Array.isArray(set.backgroundColor) ? set.backgroundColor[index % set.backgroundColor.length] : set.backgroundColor;
        ctx.fillStyle = fill || set.borderColor || cssColor(setIndex);
        const value = Number(raw) || 0;
        const height = area.h * value / max;
        const x = area.x + group * index + group / 2 - (bar * sets.length) / 2 + bar * setIndex;
        const y = area.y + area.h - height;
        roundRect(ctx, x, y, bar * .78, height, 5);
        ctx.fill();
      });
    });
    drawLabels(ctx, labels, area);
  }
  function drawLine(ctx, config, area){
    const labels = config.data?.labels || [];
    const sets = config.data?.datasets || [];
    const max = maxValue(config);
    const step = labels.length > 1 ? area.w / (labels.length - 1) : area.w;
    sets.forEach((set, setIndex) => {
      const color = set.borderColor || cssColor(setIndex);
      const data = set.data || [];
      ctx.strokeStyle = color;
      ctx.lineWidth = 3;
      ctx.lineJoin = "round";
      ctx.lineCap = "round";
      ctx.beginPath();
      data.forEach((raw, index) => {
        const x = labels.length > 1 ? area.x + step * index : area.x + area.w / 2;
        const y = area.y + area.h - (area.h * (Number(raw) || 0) / max);
        if (index === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      });
      ctx.stroke();
      ctx.fillStyle = color;
      data.forEach((raw, index) => {
        const x = labels.length > 1 ? area.x + step * index : area.x + area.w / 2;
        const y = area.y + area.h - (area.h * (Number(raw) || 0) / max);
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fill();
      });
    });
    drawLabels(ctx, labels, area);
  }
  function drawDoughnut(ctx, config, width, height){
    const labels = config.data?.labels || [];
    const data = config.data?.datasets?.[0]?.data || [];
    const colors = config.data?.datasets?.[0]?.backgroundColor || palette;
    const total = Math.max(1, data.reduce((sum, value) => sum + (Number(value) || 0), 0));
    const cx = width * .38;
    const cy = height * .48;
    const radius = Math.min(width, height) * .28;
    let start = -Math.PI / 2;
    data.forEach((raw, index) => {
      const slice = (Number(raw) || 0) / total * Math.PI * 2;
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.fillStyle = colors[index] || cssColor(index);
      ctx.arc(cx, cy, radius, start, start + slice);
      ctx.closePath();
      ctx.fill();
      start += slice;
    });
    ctx.globalCompositeOperation = "destination-out";
    ctx.beginPath();
    ctx.arc(cx, cy, radius * .58, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalCompositeOperation = "source-over";
    labels.forEach((label, index) => {
      const x = width * .68;
      const y = 42 + index * 24;
      ctx.fillStyle = colors[index] || cssColor(index);
      roundRect(ctx, x, y - 11, 12, 12, 4);
      ctx.fill();
      text(ctx, label + " " + (Number(data[index]) || 0).toFixed(1) + "h", x + 18, y, { color: "#334155", size: 12 });
    });
  }
  class Chart {
    constructor(context, config){
      this.canvas = asCanvas(context);
      this.config = config || {};
      this.render();
    }
    destroy(){
      if (!this.canvas) return;
      const box = setup(this.canvas);
      clear(box.ctx, box.width, box.height);
    }
    update(){ this.render(); }
    render(){
      if (!this.canvas) return;
      const { ctx, width, height } = setup(this.canvas);
      clear(ctx, width, height);
      const title = this.config.options?.plugins?.title?.text;
      if (title) text(ctx, title, 18, 24, { color: "#172033", size: 14, weight: 800 });
      const type = this.config.type || "bar";
      if (type === "doughnut" || type === "pie") {
        drawDoughnut(ctx, this.config, width, height);
        return;
      }
      const area = { x: 44, y: 36, w: width - 64, h: height - 76 };
      drawAxes(ctx, area);
      if (type === "line") drawLine(ctx, this.config, area);
      else drawBar(ctx, this.config, area);
      drawGoalLine(ctx, this.config, area);
    }
  }
  Chart.defaults = { font: { family: "Inter, system-ui, sans-serif" } };
  global.Chart = Chart;
})(globalThis);
